export const MULTI_AGENT_PROMPT = "Use multiple agents in parallel where useful. Divide the work into independent subtasks, wait for their results, verify the combined work, and return one consolidated answer."
export const CONTINUOUS_QA_PROMPT = "Start a continuous QA lane for this task. Use a fast Sonnet-class tester for bounded background test cycles, checkpoint exact evidence, and escalate to Opus only for repeated, ambiguous, or cross-boundary failures. Default to report-only unless I explicitly authorize a scoped repair. Use an isolated worktree, preserve unrelated changes, avoid busy-polling, and stop or wait on success, stale work, budget exhaustion, approval waits, provider limits, ambiguous requirements, or a repeated failure after one evidence-based repair attempt."
