function patchStableLibrary(source,restore=false){
  const {native,template,render,block}=stableLibrary;
  const before='jri=X('+JSON.stringify(native)+')',after='jri=X('+JSON.stringify(template)+')';
  // JSON.stringify escapes are equivalent for the ASCII native composer template.
  if(occurrences(source,before)+occurrences(source,after)!==1||occurrences(source,render)!==1)throw Error('Unsupported or ambiguous 7.8.12 prompt library anchors.');
  const blocks=[...source.matchAll(/\/\* prompt-library-7\.8\.12:v1 \*\/[\s\S]*?\/\* end prompt-library-7\.8\.12 \*\//g)];
  const reload='promptSuggestionsReload=/* pinned-append-reload:v1 */(h=>(window.addEventListener("kilo-prompt-suggestions-changed",h),Xe(()=>window.removeEventListener("kilo-prompt-suggestions-changed",h)),h))(()=>{promptSuggestionsItems=promptSuggestionsLoad(),renderPromptSuggestions()}),';
  if(blocks.length>1||blocks.length===1&&blocks[0][0].replace(reload,'')!==block)throw Error('Modified prompt library block.');
  const installed=occurrences(source,after)===1;
  if(installed!==(blocks.length===1))throw Error('Partial prompt library patch.');
  if(restore)return source.replace(after,before).replace(blocks[0]?.[0]??block,'');
  return installed?source:source.replace(before,after).replace(render,()=>render+block);
}
function patchStableLibraryCss(source,restore=false){
  const {css}=stableLibrary;
  if(source.includes('/* prompt-library-css-7.8.12:')){
    if(occurrences(source,css)!==1)throw Error('Modified prompt library CSS.');
    return restore?source.replace('\n'+css+'\n',''):source;
  }
  if(source.includes('.prompt-suggestion-launcher{'))throw Error('Unknown prompt library CSS.');
  return restore?source:source+'\n'+css+'\n';
}

export function patchWebview(source, restore=false) {
  if(source.includes('var Ge=jri()'))return patchStableLibrary(source,restore);
  const legacyTemplateApplied = source.includes("class=prompt-suggestion-chips")
  const legacyHandlerApplied = source.includes(legacyHandler)
  if (legacyTemplateApplied || legacyHandlerApplied) {
    if (!legacyTemplateApplied || !legacyHandlerApplied || !source.includes(legacyTemplateAfter) || !source.includes(legacyRenderAfter)) {
      throw new Error("prompt-suggestions: partial legacy webview patch detected; no changes made.")
    }
    source = source.replace(legacyTemplateAfter, legacyTemplateBefore).replace(legacyRenderAfter, renderBefore)
  }
  const previousTemplateApplied = source.includes(previousTemplateAfter)
  const previousHandlerApplied = source.includes(previousHandler)
  if (previousTemplateApplied || previousHandlerApplied) {
    if (!previousTemplateApplied || !previousHandlerApplied || !source.includes(previousRenderAfter)) {
      throw new Error("prompt-suggestions: partial fixed-menu webview patch detected; no changes made.")
    }
    source = source.replace(previousTemplateAfter, templateBefore).replace(previousRenderAfter, renderBefore)
  }
  const configurableV3HandlerApplied = source.includes(v3Handler)
  if (configurableV3HandlerApplied) {
    if (!source.includes(templateAfter) || !source.includes(previousV3RenderAfter)) {
      throw new Error("prompt-suggestions: partial configurable-menu v3 patch detected; no changes made.")
    }
    source = source.replace(templateAfter, templateBefore).replace(previousV3RenderAfter, renderBefore)
  }
  const configurableV2HandlerApplied = source.includes(v2Handler)
  if (configurableV2HandlerApplied) {
    if (!source.includes(templateAfter) || !source.includes(previousConfigurableRenderAfter)) {
      throw new Error("prompt-suggestions: partial configurable-menu v2 patch detected; no changes made.")
    }
    source = source.replace(templateAfter, templateBefore).replace(previousConfigurableRenderAfter, renderBefore)
  }
  const templateApplied = source.includes("data-prompt-suggestions-version=2")
  const handlerApplied = source.includes(upgradedHandler)
  if (templateApplied || handlerApplied) {
    if (!templateApplied || !handlerApplied) {
      throw new Error("prompt-suggestions: partial configurable-menu webview patch detected; no changes made.")
    }
    return source
  }
  if (occurrences(source, templateBefore) !== 1 || occurrences(source, renderBefore) !== 1) {
    throw new Error("prompt-suggestions: expected one composer template and render anchor; no changes made.")
  }
  return source.replace(templateBefore, templateAfter).replace(renderBefore, renderAfter)
}

export function patchCss(source,restore=false) {
  if(source.includes('.prompt-input-hint-pinned{'))return patchStableLibraryCss(source,restore);
  if (source.includes(".prompt-suggestion-chips{")) {
    if (!source.includes(legacyCssRules)) throw new Error("prompt-suggestions: partial legacy CSS patch detected; no changes made.")
    source = source.replace(legacyCssRules, "")
  }
  if (source.includes(previousCssRules)) source = source.replace(previousCssRules, "")
  if (source.includes(cssRules) && !source.includes(upgradedCssRules)) source = source.replace(cssRules, upgradedCssRules)
  else if (source.includes(".prompt-suggestion-launcher{") && !source.includes(upgradedCssRules)) throw new Error("prompt-suggestions: partial or unknown CSS patch detected; no changes made.")
  if (source.includes(upgradedCssRules)) return source
  if (occurrences(source, cssAnchor) !== 1) {
    throw new Error("prompt-suggestions: expected one prompt wrapper CSS anchor; no changes made.")
  }
  return source.replace(cssAnchor, `${upgradedCssRules}${cssAnchor}`)
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const checkOnly = process.argv.includes("--check"), restore=process.argv.includes("--restore")
  const [webview, css] = process.argv.slice(2).filter((arg) => !["--check","--restore"].includes(arg))
  if (!webview || !css) {
    console.error("Usage: prompt-suggestions.mjs <webview.js> <webview.css> [--check]")
    process.exit(2)
  }
  const updates = [[webview, patchWebview], [css, patchCss]].map(([target, patch]) => {
    const source = fs.readFileSync(target, "utf8")
    return [target, source, patch(source,restore)]
  })
  let missing = false
  for (const [target, source, updated] of updates) {
    if (checkOnly) {
      if (updated !== source) { console.error(`Prompt-suggestions patch is not installed in ${target}.`); missing = true }
      else console.log(`Prompt-suggestions patch is installed in ${target}.`)
      continue
    }
    if (updated === source) { console.log(`Prompt-suggestions patch already installed in ${target}.`); continue }
    const backup = `${target}.pre-prompt-suggestions`
    if (!fs.existsSync(backup)) fs.copyFileSync(target, backup)
    const temporary = `${target}.prompt-suggestions-${process.pid}`
    fs.writeFileSync(temporary, updated, { mode: fs.statSync(target).mode & 0o777 })
    fs.renameSync(temporary, target)
    console.log(`Patched ${target} (backup ${backup})`)
  }
  if (missing) process.exit(1)
}
